// length with each argument converted to a default spew Formatter interface.\nfunc convertArgs(args []interface{}) (formatters []interface{}) {\n\tformatters = make([]interface{}, len(args))\n\tfor index, arg := range args {\n\t\tformatters[index] = NewFormatter(arg)\n\t}\n\treturn formatters\n}\n"}, {"lang": "go", "shikiLang": "go", "name": "go-chi__chi__middleware_sunset.go", "code": "package middleware\n\nimport (\n\t\"net/http\"\n\t\"time\"\n)\n\n// Sunset set Deprecation/Sunset header to response\n// This can be used to enable Sunset in a route or a route group\n// For more: https://www.rfc-editor.org/rfc/rfc8594.html\nfunc Sunset(sunsetAt time.Time, links ...string) func(http.Handler) http.Handler {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\tif !sunsetAt.IsZero() {\n\t\t\t\tw.Header().Set(\"Sunset\", sunsetAt.Format(http.TimeFormat))\n\t\t\t\tw.Header().Set(\"Deprecation\", sunsetAt.Format(http.TimeFormat))\n\n\t\t\t\tfor _, link := range links {\n\t\t\t\t\tw.Header().Add(\"Link\", link)\n\t\t\t\t}\n\t\t\t}\n\t\t\tnext.ServeHTTP(w, r)\n\t\t})\n\t}\n}\n"}, {"lang": "go", "shikiLang": "go", "name": "gin-gonic__gin__recovery.go", "code": "// Copyright 2014 Manu Martinez-Almeida. All rights reserved.\n// Use of this source code is governed by a MIT style\n// license that can be found in the LICENSE file.\n\npackage gin\n\nimport (\n\t\"bufio\"\n\t\"bytes\"\n\t\"cmp\"\n\t\"errors\"\n\t\"fmt\"\n\t\"io\"\n\t\"log\"\n\t\"net/http\"\n\t\"net/http/httputil\"\n\t\"os\"\n\t\"runtime\"\n\t\"strings\"\n\t\"syscall\"\n\t\"time\"\n\n\t\"github.com/gin-gonic/gin/internal/bytesconv\"\n)\n\nconst (\n\tdunno     = \"???\"\n\tstackSkip = 3\n)\n\n// RecoveryFunc defines the function passable to CustomRecovery.\ntype RecoveryFunc func(c *Context, err any)\n\n// Recovery returns a middleware that recovers from any panics and writes a 500 if there was one.\nfunc Recovery() HandlerFunc {\n\treturn